class Autobuy {
    constructor(buyArr) {
        this.index = 0;
        this.buy = function () {
            if (this.index >= buyArr.length) return;
            let id = buyArr[this.index];
            if (id <= 100) {
                if (player.skins[id]) this.index++;
                else if (player.points >= findID(store.hats, id).price) {
                    packet("c", 1, id, 0, "autoBuy");
                    this.index++;
                }
            } else {
                id -= 100;
                if (player.tails[id]) this.index++;
                else if (player.points >= findID(store.accessories, id).price) {
                    packet("c", 1, id, 1, "autoBuy");
                    this.index++;
                }
            };
        }
    }
}
