class Damages {
    constructor(items) {
        // 0.75 1 1.125 1.5
        this.calcDmg = function (dmg, val) {
            return dmg * val;
        };
        this.getAllDamage = function (dmg) {
            return [
                this.calcDmg(dmg, 0.75),
                dmg,
                this.calcDmg(dmg, 1.125),
                this.calcDmg(dmg, 1.5),
            ];
        };
        this.getAllPDamage = function (dmg) {
            return [this.calcDmg(dmg, 0.75), dmg];
        };
        this.weapons = [];
        for (let i = 0; i < 16; i++) {
            let wp = items.weapons[i];
            let name =
                wp.name.split(" ").length <= 1
                    ? wp.name
                    : wp.name.split(" ")[0] + "_" + wp.name.split(" ")[1];
            this.weapons.push(
                i > 8
                    ? wp.Pdmg
                        ? this.getAllPDamage(wp.Pdmg)
                        : this.getAllDamage(wp.dmg)
                    : this.getAllDamage(wp.dmg)
            );
            this[name] = this.weapons[i];
        }
    }
}
globalThis.greetings = false;
globalThis.getGreeting = function() {
    const hour = new Date().getHours();
    if (hour < 12) return "Good Morning!";
    else if (hour < 18) return "Good Afternoon!";
    else return "Good Evening!";
}
globalThis.greeting = function() {
    if (!greetings) {
        greetings = true;
        const frameMsg = Object.assign(document.createElement("div"), {
            innerHTML: `${getGreeting()}`,
            style: `
                    position: fixed;
                    top: -100px;
                    left: 50%;
                    transform: translateX(-50%);
                    font-size: 2rem;
                    color: white;
                    z-index: 9999;
                    opacity: 3;
                    transition: top 0.5s ease-in-out, opacity 0.5s ease-in-out;
                    padding: 10px;
                    background-color: rgba(0, 0, 0, 0.2);
                    border: 2px solid #0000;
                    border-radius: 5px;
                    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
                `,
        });
        document.body.appendChild(frameMsg);
        setTimeout(function () {
            frameMsg.style.top = "7%";
            frameMsg.style.opacity = "1";
        }, 100);
        setTimeout(function () {
            frameMsg.style.top = "-100px";
            frameMsg.style.opacity = "0";
            setTimeout(function () {
                frameMsg.remove();
                greetings = false;
            }, 500);
        }, 3000);
    }
}
