globalThis.Do = function(e, t, i) {
    const n = e.lineWidth || 0;
    (i /= 2), e.beginPath();
    let s = (PI2) / t;
    for (let r = 0; r < t; r++)
        e.lineTo(
            i + (i - n * 0.5) * cos(s * r),
            i + (i - n * 0.5) * sin(s * r)
        );
    e.closePath();
}
