globalThis.showItemInfo = function(item, isWeapon, isStoreItem) {
    if (player && item) {
        UWUTILS.removeAllChildren(itemInfoHolder);
        itemInfoHolder.classList.add("visible");
        UWUTILS.generateElement({
            id: "itemInfoName",
            text: UWUTILS.capitalizeFirst(item.name),
            parent: itemInfoHolder,
        });
        UWUTILS.generateElement({
            id: "itemInfoDesc",
            text: item.desc,
            parent: itemInfoHolder,
        });
        if (isStoreItem) {
        } else if (isWeapon) {
            UWUTILS.generateElement({
                class: "itemInfoReq",
                text: !item.type ? "primary" : "secondary",
                parent: itemInfoHolder,
            });
        } else {
            let con = item.req.length;
            for (let i = 0; i < con; i += 2) {
                UWUTILS.generateElement({
                    class: "itemInfoReq",
                    html:
                        item.req[i] +
                        "<span class='itemInfoReqVal'> x" +
                        item.req[i + 1] +
                        "</span>",
                    parent: itemInfoHolder,
                });
            }
            if (item.group.limit) {
                UWUTILS.generateElement({
                    class: "itemInfoLmt",
                    text:
                        (player.itemCounts[item.group.id] || 0) +
                        "/" +
                        (config.isSandbox ? 99 : item.group.limit),
                    parent: itemInfoHolder,
                });
            }
        }
    } else itemInfoHolder.classList.remove("visible");
}
// RESIZE:
globalThis.resize = function() {
    screenWidth = window.innerWidth;
    screenHeight = window.innerHeight;
    let scaleFillNative =
        mathMax(screenWidth / maxScreenWidth, screenHeight / maxScreenHeight) *
        pixelDensity;
    gameCanvas.width = screenWidth * pixelDensity;
    gameCanvas.height = screenHeight * pixelDensity;
    gameCanvas.style.width = screenWidth + "px";
    gameCanvas.style.height = screenHeight + "px";
    mainContext.setTransform(
        scaleFillNative,
        0,
        0,
        scaleFillNative,
        (screenWidth * pixelDensity - maxScreenWidth * scaleFillNative) * 0.5,
        (screenHeight * pixelDensity - maxScreenHeight * scaleFillNative) * 0.5
    );
    if (larpModeActivated) {
        mainContext.translate(maxScreenWidth * 0.5, maxScreenHeight * 0.5);
        mainContext.rotate(rotation);
        mainContext.translate(-maxScreenWidth * 0.5, -maxScreenHeight * 0.5);
    }
}
