globalThis.findAvailableAngles = function(item, thisAng, vel, xd = PI / (traps.in ? 60 : 75)) { // originally 60
    if (!item) return [];
    if (traps.in && !traps.info.assumeBreak) thisAng = (traps.aim - PI / 1.5);
    const con1 = nearHacker.inTrap && nearHacker.inTrap.health <= 292.05;
    const conditions = con1 && nearHacker.weaponIndex == 10 && nearHacker.weaponReload > 0 && nearHacker.weaponReload < 112;/* && nearHacker.weaponIndex == 10 && nearHacker.weaponReload > 0 && nearHacker.weaponReload < 112*/;
    //   const givenAngle = gAng;
    const interval = xd;
    const potentialAngles = []// {onPlayer:[],norm:[]};
    const x = vel ? player.x3 : player.x2
    const y = vel ? player.y3 : player.y2
    const i = items.list[item];
    const tmpS = (35 + i.scale + (i.placeOffset || 0));
    const lim = thisAng + PI2;//(traps.in ? PI / 1.5 : PI2);
    let index = -1;
    for (let offset = thisAng; offset <= lim; offset += interval) {
        index++;
        const angle = offset;
        let used = false;
        const tmpX = x + (tmpS * cos(offset));
        const tmpY = y + (tmpS * sin(offset));
        for (let u = 0; u < usedAngles.length; u++) {
            const usedAngle = usedAngles[u];
            const dx = tmpX - usedAngle.x;
            const dy = tmpY - usedAngle.y;
            const dist = dx*dx + dy*dy;
            if (dist <= 400) {
                used = true;
                break;
            }
        }
        if (used) continue;
        const obj = { x: tmpX, y: tmpY, auto: true, id: i.id, scale: i.scale, angle: offset, offset: tmpS, item: i, collide: [], points: 0, indx: index, name: i.name, overlap: [], preplacer: [], sids: [], intercepts: [], knockback: [] }
        const canPlace = con1 ? conditions ? objectManager.checkItemLocation4(tmpX, tmpY, i.scale, 0.6, i.id, false, true, obj) :  objectManager.checkItemLocation9(tmpX, tmpY, i.scale, 0.6, i.id, false, true, obj) : secPacketRatio <= .09 ? objectManager.checkItemLocation3(tmpX, tmpY, i.scale, 0.6, i.id, false, true, obj) : objectManager.checkItemLocationAutoPlacing(tmpX, tmpY, i.scale, 0.6, i.id, false, true)
        if (canPlace) potentialAngles.push(obj);
    }
    //showAngles = potentialAngles;
    return potentialAngles;
}
