globalThis.getMidAngle = function(a1, a2) {
    let diff = a2 - a1;
    if (diff > Math.PI) diff -= Math.PI * 2;
    if (diff < -Math.PI) diff += Math.PI * 2;
    return a1 + diff * 0.5;
}
