globalThis.knockInto = function(spike, objs, theEnemy, dir, cosX, sinY) {
    //const timeStart = performance.now()
    let found = false, ang = null;
    const obj = { inEscapable: false, doubleSpike: false, building1: null, closest: Infinity, bounce: false, dmg: 0, spikeCount: 0, trapCount: 0, total: 0, newPos: { ...theEnemy } }
    for (let i = 0; i < objs.length; i++) {
        const objekt = objs[i];
        if (obj.dist2 > 340 || !objekt.dmg && !objekt.isCactus && !objekt.trap) continue;
        const distance = hypot(theEnemy.x2 - objekt.x, theEnemy.y2 - objekt.y);//dist2(theEnemy,objekt)
        if (distance > 280) continue;
        const closestPoint = {x: theEnemy.x2 + distance * cosX, y: theEnemy.y2 + distance * sinY};//  hypot2(player.x2-a.x,player.y2-a.y)
        const scale = objekt.trap ? 47.5 : objekt.colScale;
        const closestDist = squareDist(closestPoint.x - objekt.x, closestPoint.y - objekt.y);
        if (closestDist > scale*scale) continue;
        if ((objekt.dmg || objekt.isCactus) && distance <= 200 && distance > 110 && closestDist < (scale - 12) ** 2) obj.inEscapable = true;
        let pushed = false;
        const condition = !objekt.trap && distance <= 245 && (distance >= 135 || playerHasSyncWeapon && (distance >= 155 || squareCdf(spike, objekt) >= 12100));
        if (found && !objekt.trap && obj.building1.dmg && abs(distance - obj.closest) <= 16.6767) {
            const relative = dAng(getMidAngle(caf(nearHacker, obj.building1), caf(nearHacker, objekt)), dir);
            if (relative <= 0.4) {
                spike.doubleSpike = true;
                obj.doubleSpike = true;
                pushed = true;
                if (condition) {
                    obj.bounce = true;
                    obj.ang = relative;
                    //spike.closestPoint = closestPoint;
                }
            }
        }
        if (distance < obj.closest) {
            obj.building1 = objekt;
            obj.closest = distance;
            if (!pushed) {
                found = true;
                if (obj.doubleSpike) obj.doubleSpike = false, spike.doubleSpike = false;
            }
        }
        //const dist = squareDist(objekt, spike);
        if (!condition || pushed) continue;
        const angD = dAng(dir, caf(spike, objekt));
        if (angD > 0.28 - distance * 0.001) continue;
        obj.ang = angD;
        obj.bounce = true;
        //spike.closestPoint = closestPoint;
    }
    //console.log(performance.now() - timeStart)
    return obj;
    // dAng() <= .19 + 45 distance too
}
