globalThis.checkPlacement = function(obj, canPlace) {
    //consolelog(obj, priority, ppAmt, timer, canPlace);
    const item = obj.item;
    placeVisible.push({
        id: item.id,
        x: obj.x,
        y: obj.y,
        name: item.name,
        scale: item.scale,
        dir: obj.angle,
        pre: obj.preplace,
        re: obj.re,
        tick: game.tick,
        auto: obj.auto,
        owner: { sid: player.sid }
    });
    if (obj.placePriority && secPacketRatio <= .09) {
        if (obj.preplace) {
            preplaceLoc.push(obj);
            objectManager.add(game.tick, obj.x, obj.y, obj.angle, obj.scale, null, items.list[obj.item.id], !0, { sid: player.sid }, 0, 0, 1, 1, 1, 0) // comment for tests
            return true;
        } else {
            placeObj(obj.item.id, obj.angle)
            objectManager.add(game.tick, obj.x, obj.y, obj.angle, obj.scale, null, items.list[obj.item.id], !0, { sid: player.sid }, 0, 0, 1, 1, 0, 0)
            return true;
        }
    }
    canPlace = objectManager.checkItemLocationAutoPlacing(obj.x, obj.y, obj.scale, .6, obj.item.id, false, false)
    if (canPlace) {
        placeObj(obj.item.id, obj.angle)
        objectManager.add(game.tick, obj.x, obj.y, obj.angle, obj.scale, null, items.list[obj.item.id], !0, { sid: player.sid }, 0, 0, 1, 1, 0, 1)
        return true;
    }
    return false;
}
