globalThis.pushObject1Dist = null;
globalThis.pushObject1Scale = null;
globalThis.pushObject1 = null;
globalThis.wyndAP = function(Z, t, b, GG, _, enemyV, useVel) {
    const predictedHat = hatSwitcher(true);
    if (!nearHacker || nearHacker.hitSpike || !nearHacker.inTrap || player.skinIndex==45) {
        pushing = false;
        pusher = false;
        boostPusher = false;
        pushPosition = 'not';
        pushVector = 'not'
        pushCoords = 'not'//{x:null,y:null}
        sendMoveDir();
        return false;
    }
    AUTOPUSHER_spikes.length = 0;
    AUTOPUSHER_traps.length = 0;
    pushObject1Dist = null;
    pushObject1Scale = null;
    pushObject1 = null;
    // addChatLog(`${dist(nearHacker,nearHacker.np.decel)} ${tick}`,'', '#5c0620',false,true);
    let overrideDir;
    pushing = false;
    boostPusher = false;
    pusher = false;
    // useVel = true;
    //  enemyV = useVel ? nearHacker.np.decel : nearHacker
    Z = nearHacker.aim2
    pushVector = { x: cos(Z), y: sin(Z), objs: [], dev: null, dir: null };
    const pushVectorObjs = pushVector.objs;
    AUTOPUSHER_collTrap = nearHacker.inTrap
    AUTOPUSHER_collTrapX = AUTOPUSHER_collTrap.x;
    AUTOPUSHER_collTrapY = AUTOPUSHER_collTrap.y
    if (configs.trapPusher) {
        for (let i = 0; i < nearObjects.length; i++) {
            const x = nearObjects[i];
            if (!x.active || !x.dmg && !x.trap && !x.isCactus) continue;
            if (x.dmg && x.inClan || x.isCactus) AUTOPUSHER_spikes.push(x);
            else if (x.trap && x.inClan) AUTOPUSHER_traps.push(x);
        }
    } else {
        for (let i = 0; i < nearObjects.length; i++) {
            const x = nearObjects[i];
            if (!x.active || !x.dmg && !x.trap && !x.isCactus) continue;
            if (x.dmg && x.inClan || x.isCactus) AUTOPUSHER_spikes.push(x);
        }
    }
    for (let i = 0; i < AUTOPUSHER_spikes.length + AUTOPUSHER_traps.length; i++) {
        const trap = i >= AUTOPUSHER_spikes.length;
        if (pushVectorObjs.length && trap) break;
        _ = trap ? AUTOPUSHER_traps[i - AUTOPUSHER_spikes.length] : AUTOPUSHER_spikes[i];
        if (!_) continue;
        const scaler = _.escapeScale;
        const trapDist = squareCdf(AUTOPUSHER_collTrap, _);
        // 14400 = 120**2
        if (trap && (trapDist > 14400 || !nearObjects.find2((e) => (e.dmg && e.inClan || e.isCactus) && e.active && checkDist(e, _, 0, 0, 75 + e.escapeScale) && dotAngle(e.x, e.y, _.x, _.y, AUTOPUSHER_collTrapX, AUTOPUSHER_collTrapY, 0)))) continue;
        // id 6-9 are all spikes
        if (!trap && (trapDist > (75 + scaler) ** 2 || pushVectorObjs.length === 1 && (trapDist > (72 + scaler) ** 2 || squareCdf(_,pushObject1) > (pushObject1Scale + scaler + 42.5)**2))) continue;
        if (pushVectorObjs.length === 0 || pushVectorObjs.length === 1 && pushObject1Dist <= (pushObject1Scale + scaler + 67)**2 && dotAngle(AUTOPUSHER_collTrapX, AUTOPUSHER_collTrapY, pushObject1.x, pushObject1.y, _.x, _.y, 0.10451614404)) {
            const a = fastAtan2(_.y - nearHacker.y2, _.x - nearHacker.x2);
            const d = 170 - cdf(_, nearHacker);
            pushVector.x += d * cos(a);
            pushVector.y += d * sin(a);
            if (!pushVectorObjs.length) pushObject1 = _, pushObject1Dist = trapDist, pushObject1Scale = scaler;
            pushVectorObjs.push(_);
            pushingToTrap = trap;
        }
        //if (pushObject1) consolelog(dAng(caf(_, AUTOPUSHER_collTrap), caf(pushObject1, AUTOPUSHER_collTrap)), round(cdf(_, pushObject1)) - (pushObject1.scale + _.scale));
        // consolelog(pushVectorObjs.length, dist(_, AUTOPUSHER_collTrap) <= 50 + _.scale + 15 , pushVectorObjs.length && dist(_,pushObject1) <= pushObject1.scale + _.scale + 21, !_.ignoreCollision)
        const dx = AUTOPUSHER_collTrapX - nearHacker.x2;
        const dy = AUTOPUSHER_collTrapY - nearHacker.y2;
        if (dot(pushVector, dx, dy) > 0){
            pushVector.x += dx*2;
            pushVector.y += dy*2;
        }
        if (pushVectorObjs.length > 1) break;
    }// 36 lowest so far
    if (pushVector.x**2 + pushVector.y**2 > 20) {
        const spike = pushObject1;
        const distToEnemy = nearHacker.dist2;
        const tau = dAng(Z, fastAtan2(pushVector.y, pushVector.x));
        const decide = cdf(nearHacker, spike) <= spike.scale + 38.75
        const opposite = 3600 + distToEnemy * distToEnemy - (28.5 + (decide ? 71.5 : 0)) * distToEnemy * cos(tau);
        const deviance = acos((distToEnemy * distToEnemy + opposite - 3600) / (2 * distToEnemy * sqrt(opposite)));
        const sign = Math.sign((nearHacker.x2 - player.x2) * (pushVector.y) - (nearHacker.y2 - player.y2) * (pushVector.x))
        if (!isNaN(deviance)) {
            overrideDir = Z - sign * deviance;
            let distanceToTarget = nearHacker.dist2 + 30;
            const angToSpike = caf(nearHacker, spike);
            let p2 = { x2: player.x2, y2: player.y2, xVel: player.xVel, yVel: player.yVel };
            p2.buildIndex = -1;
            p2.tailIndex = predictedHat >= 200 ? predictedHat - 200 : player.tailIndex;
            p2.skinIndex = predictedHat < 200 ? predictedHat : player.skinIndex;
            p2.weaponIndex = player.weaponIndex;
            const pushThreat = runInto(p2, overrideDir, calcVelNoCollision(p2, overrideDir, { maxSpeed: Math.max(1.2, player.maxSpeed) }, 1));
            //if (nearObjects.filter2((e) => e.trap && e?.owner?.sid == player.sid && cdf(e, newPos) <= 50)?.length >= 2) {
            if (pushingToTrap || dAng(angToSpike, nearHacker.aim2) <= 1.5 || nearHacker.dist2 < 100) {
                if (pushingToTrap) addMenuChText(null, `Trap Push on ${nearHacker.name} [${nearHacker.sid}]`, "#670000");
                pushing = true;
                pusher = true;
                boostPusher = true;
                pushVector.dir = overrideDir;
                drawLine = {x: cos(overrideDir) * distToEnemy, y: sin(overrideDir) * distToEnemy};
                player.moveDirection = overrideDir;
                player.moveSin = sin(overrideDir);
                player.moveCos = cos(overrideDir);
                updatePredictPos(null, 6, null);
            } else {
                boostPusher = false;
                pushing = true;
                pusher = true;
                sendMoveDir();
                pushVector.dir = overrideDir;
            }
        } else {
            boostPusher = false;
            pushing = false;
            pusher = false;
            sendMoveDir()
        }
            /*} else sendMoveDir()*/
        } else {
            boostPusher = false;
            pushing = false;
            pusher = false;
            sendMoveDir()
        }
}
globalThis.moveToPath = function(time,distance, x){
    if (paths && paths.length && (/*macro.z || */pusher==false&&pushing)) {
        let spliceIndex = 0,startIndex=0;;
        if (pushing&&paths.length*7>=360) {
            sendMoveDir();
            return;
        }
        while (startIndex < paths.length) {
            const pointX = paths[startIndex];
            const pointY = paths[startIndex + 1];
            const dx = player.x2 - pointX;
            const dy = player.y2 - pointY;
            const distanceToPlayer = dx*dx+dy*dy;
            let threshold = x ? 100 : 1225;
            if (distanceToPlayer <= threshold) spliceIndex += 2;
            else if (!pushing) break;
            if (pushing&&distanceToPlayer>distance){
                sendMoveDir()
                return false
            }
            startIndex += 2;
        }
        if (spliceIndex + 2 < paths.length) {
            const nextPoint = { x: paths[spliceIndex], y: paths[spliceIndex + 1] };
            packet("9", caf(player, nextPoint),'pathfinder');
            paths.splice(0, spliceIndex);
        }
    }
    //consolelog(Date.now()-time,"generate time")
    return true;
}
globalThis.autopush = function(ez, e, t) {
    const pushTarget = enemy.find2((e) => e.dist2 <= 300 && e.trapped)
    if (nearHacker.hitSpike && pusher) {
        my.autoPush = false;
        pushing = false;
        pusher = false;
        boostPusher = false;
        pushPosition = 'not';
        pushCoords = 'not'
        pushVector = 'not';
        packet("9", nearHacker.aim2 + PI, 1);
        return false;
    } else if (nearHacker.hitSpike || nearHacker.dist2 > 400 || !nearHacker.trapped || player.skinIndex == 45) {
        my.autoPush = false;
        pushing = false;
        pusher = false;
        boostPusher = false;
        pushPosition = 'not';
        pushCoords = 'not'
        pushVector = 'not';
        sendMoveDir();
        return false;
    }
    const nx = nearHacker.x2;
    const ny = nearHacker.y2;
    if (!ez) ez = [];
    let best = null;
    let bestDist = Infinity;
    for (let i = 0; i < liztobj.length; i++) {
        const e = liztobj[i];
        if (!e.active || !e.isCactus && !e.dmg || ez.includes(e.sid)) continue;
        if (cdf(nearHacker.inTrap, e) <= 75 + e.escapeScale && (e.isCactus || player.isTeam(e.owner.sid))) {
            const d = squareDist(e.x - nx, e.y - ny);
            if (d < bestDist) {
                bestDist = d;
                best = e;
            }
        }
    }
    if (!best) {
        pusher = false;
        pushing = false;
        boostPusher = false;
        pushPosition = 'not';
        pushVector = 'not';
        pushCoords = 'not'
        sendMoveDir()
        return false;
    }
    const x = nearHacker.inTrap.x;
    const y = nearHacker.inTrap.y;
    const bx = best.x;
    const by = best.y;
    const sx = nx - bx;
    const sy = ny - by;
    const px = nx - player.x2;
    const py = ny - player.y2;
    const tx = nx - x;
    const ty = ny - y;
    const tsx = bx - x;
    const tsy = by - y;
    const sm = hypot(sx,sy);
    sTE = {
        x: sx / sm,
        y: sy / sm
    };
    const pm = hypot(px, py);
    pTE = {
        x: px / pm,
        y: py / pm
    };
    const tm = hypot(tx, ty);
    tTE = {
        x: tx / tm,
        y: ty / tm
    };
    const tsm = hypot(tsx, tsy);
    let tTS = {
        x: tsx / tsm,
        y: tsy / tsm
    };
    const a = [fastAtan2(sTE.y, sTE.x), fastAtan2(tTE.y, tTE.x), fastAtan2(pTE.y, pTE.x)];
    const aa = [(a[0] + a[1]) * 0.5, (a[0] + a[2]) * 0.5];
    const av = [
        { x: cos(aa[0]), y: sin(aa[0]) },
        { x: cos(aa[1]), y: sin(aa[2]) }
    ];
    dPAP = (sTE.x * pTE.x) + (sTE.y * pTE.y)// (av[0].x * pTE.x) + (av[0].y * pTE.y);
    sos3 = best.escapeScale;
    apS = best;
    pushPosition = {
        x: nearHacker.x2 + sTE.x * (dPAP + sos3),
        y: nearHacker.y2 + sTE.y * (dPAP + sos3)
    };
    t = squareCdf(player, pushPosition) <= 20000 && (dAng(caf(nearHacker, best), nearHacker.aim2) <= 1.3 && dAng(caf(player, pushPosition), nearHacker.aim2) <= 1.6); // 2 or 2.3
    let ar = { x: nearHacker.x2, y: nearHacker.y2, pathScale: 35, do: true };
    // let o = nearObjects;
    let obstacles = t ? nearObjects : nearObjects.concat(ar);
    let tX = Date.now();
    paths = [];
    if (t) wyndAP();
    else {
        // changed + 30 to + 35, let's see if better
        pathfind({
            player: { x2: player.x2, y2: player.y2, sid: player.sid },
            target: { x: nearHacker.x2 + sTE.x * (dPAP + sos3 + 35), y: nearHacker.y2 + sTE.y * (dPAP + sos3 + 35) },
            buildings: obstacles,
            clan: allianceSids
        }).then(foundPath => {
            let p = foundPath;
            pusher = false;
            pushing = true;
            if (!p) {
                pusher = false;
                pushing = false;
                boostPusher = false;
                pushPosition = 'not';
                pushVector = 'not';
                pushCoords = 'not'
                // ez.push(s[0].sid);
                // autopush(ez);
                sendMoveDir();
                return false;
            }
            e = moveToPath(tX, 129600, true);
            if (!e) {
                pusher = false;
                boostPusher = false;
                pushing = false;
                pushPosition = 'not';
                pushVector = 'not';
                pushCoords = 'not'
                //  ez.push(s[0].sid);
                paths = [];
                // autopush(ez);
                sendMoveDir();
                return;
            }

        }).catch(error => {
            sendMoveDir();
            pushing = false;
            boostPusher = false;
            pusher = false;
            pushPosition = 'not';
            return false;
        });
    }
}
