// ADD NEW PLAYER:
globalThis.turks = ["banana", "diama ykr", "x-x", "x-", "x-shadow", "chucky", "Tuana"];
globalThis.addPlayer = function(data, isYou, bot) {
    if (botSIDs.includes(data[1]) && !isYou) return
    if (bot) {
        let tmpPlayer = findPlayerByID(data[0]);
        if (!tmpPlayer) {
            if (isYou) {
                Object.assign(bot, new Player(data[0], data[1], config, UWUTILS, projectileManager, objectManager, players, ais, items, hats, accessories));
                tmpPlayer = bot;
            } else tmpPlayer = new Player(data[0], data[1], config, UWUTILS, projectileManager, objectManager, players, ais, items, hats, accessories);
            tmpPlayer.displayText = `${data[2]} [${data[1]}]`;
            if (turkList.includes(tmpPlayer.sid)) tmpPlayer.isTurk = true;
            if (data[2] && turks.includes(data[2].toLowerCase())) turkList.push(data[1]);
            players.push(tmpPlayer);
            bot.food = bot.points = bot.wood = bot.stone = 100;
            tmpPlayer.visible = false;
            tmpPlayer.oldPos = {
                x2: undefined,
                y2: undefined,
            };
            tmpPlayer.x2 = undefined;
            tmpPlayer.y2 = undefined;
            tmpPlayer.x3 = undefined;
            tmpPlayer.y3 = undefined;
            tmpPlayer.setData(data);
            if (!isYou && !botSIDs.includes(data[1])) addMenuChText(null, `Bot ${bot.sid} encountered ${data[2]} {${data[1]}}`, "lime");
        } else if (Date.now() - tmpPlayer.lastEncounter > 1000 && !isYou && !botSIDs.includes(data[1])) addMenuChText(null, `Bot ${bot.sid} encountered ${data[2]} {${data[1]}}`, "lime");
        tmpPlayer.lastEncounter = Date.now();
        if (!tmpPlayer || !tmpPlayer.alive || isYou) tmpPlayer.spawn(isYou ? true : null);
    } else {
        let tmpPlayer = findPlayerByID(data[0]);
        if (!tmpPlayer) {
            tmpPlayer = new Player(
                data[0],
                data[1],
                config,
                UWUTILS,
                projectileManager,
                objectManager,
                players,
                ais,
                items,
                hats,
                accessories
            );
            if (turkList.includes(tmpPlayer.sid)) tmpPlayer.isTurk = true;
            //tmpPlayer.uniqueColor = generateRandomColor();
            tmpPlayer.displayText = `${data[2]} [${data[1]}]`;
            players.push(tmpPlayer);
            if (data[1] != playerSID) addMenuChText(null, `Found ${data[2]} {${data[1]}}`, "lime");
        } else if (Date.now() - tmpPlayer.lastEncounter > 1000 && data[1] != playerSID) addMenuChText(null, `Found ${data[2]} {${data[1]}}`, "lime");
        tmpPlayer.lastEncounter = Date.now();
        if (!tmpPlayer || !tmpPlayer.alive) tmpPlayer.spawn(isYou ? true : null);
        tmpPlayer.setData(data);
        if (isYou) {
            gameUI.style.display = "block";
            ageText.textContent = "AGE 1";
            ageBarBody.style.width = "0%";
            if (!player) {
                getEl("noticationDisplay").remove();
                window.prepareUI(tmpPlayer);
                /*
                for (let i = 0; i < aiManager.aiTypes.length; i++) {
                    addAnimalToTracker(i);
                }*/
            }
            getEl("scoreDisplay").textContent = "100";
            getEl("woodDisplay").textContent = "100";
            getEl("foodDisplay").textContent = "100";
            getEl("stoneDisplay").textContent = "100";
            player = tmpPlayer;
            player.fS = false;
            player.botObjects = [];
            player.age = 1;
            player.playerSIDs = [];
            player.food = player.points = player.wood = player.stone = 100;
            player.packets = 0;
            player.sendPacket = (packet, data) => {
                if (!player.fS) {
                    player.fS = true;
                    setTimeout(()=>{
                        player.fS = false;
                        player.packets = 0;
                    }, 1000);
                }
                player.packets++;
                if (player.packets>=85) return;
                if (packet == "9") player.clientDir = data[0];
                if (packet == "K") player.autoGathering = !player.autoGathering;
                sendWS(msgpack.encode([c2s[packet], data]));
            }
            renderAllianceListInLogs();
            player.kbPotential = 30;
            player.replaceTickThreat = 0;
            player.primaryXP = 0;
            player.alive = true;
            player.secondaryXP = 0;
            player.primary = [];
            camX = player.x;
            camY = player.y;
            my.lastDir = 0;
            updateItems();
            updateItemCountDisplay();
            if (player.skins[7]) my.reSync = true;
        }
    }
}
// REMOVE PLAYER:
globalThis.removePlayer = function(id) {
    let tmpPlayer = findPlayerByID(id);
    addMenuChText(null,
        (tmpPlayer ? (tmpPlayer.name + " [" + tmpPlayer.sid + "]") : id) + " left the game",
        "red"
    );
    openSlots++;
    if (tmpPlayer?.sid) {
        if (annoyingList.includes(tmpPlayer.sid)) annoyingList.splice(annoyingList.indexOf(tmpPlayer.sid), 1)
        if (friendList.includes(tmpPlayer.sid)) friendList.splice(friendList.indexOf(tmpPlayer.sid), 1)
    }
    if (tmpPlayer) players.splice(players.indexOf(tmpPlayer), 1);
}
// dune mod dmgpot
globalThis.sortWeaponVariant = function(id) {
    switch (id) {
        case 0:
            return 1;
            break;
        case 1:
            return 1.1;
            break;
        case 2:
            return 1.18;
            break;
        case 3:
            return 1.18;
            break;
        default:
            return 1;
            break;
    }
}
globalThis.sortVariantSrc = function(id) {
    switch (id) {
        case 0:
            return "";
            break;
        case 1:
            return "_g";
            break;
        case 2:
            return "_d";
            break;
        case 3:
            return "_r";
            break;
    }
}
