// UPDATE HEALTH:
globalThis.updateHealth = function(sid, value) {
    if (sid == player.sid) {
        player.predictHealth = value;
        console.log("dmg: ", player.health - value, "tick: ", game.tick);
        if (value <= 0) {
            console.log("DEATH", game.tick);
            console.log("DEATH", game.tick);
            console.log("DEATH", game.tick);
            game.tickBase(() => {
                player.predictHealth = 100;
            }, 7);
        } else if (player.skinIndex == 56) buyEquip(6, 0);
    }
    let tmpObj = findPlayerBySID(sid);
    if (!tmpObj) return;
    let oldHealth = tmpObj.health;
    if (oldHealth < value) {
        tmpObj.timeHealed = performance.now();
        let time = (tmpObj.timeHealed - tmpObj.timeDamaged) - (tmpObj.shameCount <= tmpObj.oldShameCount) * game.tickRate;
        tmpObj.pinge = time;
    } else if (oldHealth > value) {
        tmpObj.timeDamaged = performance.now();
        tmpObj.lastDamage = game.tick;
    }
    tmpObj.oldHealth = tmpObj.health;
    tmpObj.health = value;
    let dmg = tmpObj.oldHealth - value;
    if (tmpObj.health <= 0) {
        textManager.stack.push({
            crit: true,
            x: tmpObj.x3,
            y: tmpObj.y3,
            value: tmpObj.lastHealth - tmpObj.health,
            target: tmpObj
        });
        tmpObj.doDamageText = false;
    } else if (tmpObj.sid == player.sid ? dmg < 0 : dmg > 0) tmpObj.doDamageText = true;
    const bot = bots.find2((e) => e.sid == sid);
    if (bot) {
        bot.health = value;
        if (dmg > 0) {
            if (dmg == 5 && bot.reSync) bot.reSync = false, bot.bullTick = game.tick;
            bot.lastHit = game.tick;
            if (bot.skinIndex != 45 && bot.health != 100 && (bot.health < (bot.skins[7] ? 66 : 66) && tmpObj.shameCount < 7)) bot.heal(value);
        }
    }
    //console.log(tmpObj.checkSpike, dmg, (dmg != 0 && tmpObj.checkSpike && (tmpObj.checkSpike == dmg || tmpObj.checkSpike == dmg * 0.75)))
    if (dmg != 0 && tmpObj.checkSpike && (abs(tmpObj.checkSpike - dmg) < 0.1 || abs(tmpObj.checkSpike * 0.75 - dmg) < 0.1)) {
        tmpObj.hitSpike = true;
        tmpObj.spikeDmgTick = game.tick;
        //if (tmpObj.sid == player.sid && nearHacker.primaryReload <= 111 && (nearHacker.primaryIndex == 5 || nearHacker.primaryIndex == 4)) my.anti0tick = 1;
    }
    if ((tmpObj.hps || tmpObj.cheese) && (dmg < 0 && (dmg >= ((tmpObj.cheeze ? -10 : 0) - tmpObj.hps) && value == 100 || value < 100 && dmg == ((tmpObj.cheeze ? -10 : 0) - tmpObj.hps)))) tmpObj.cheesed = true;
    if (tmpObj.cheese && ((game.tick - player.bullTick) % 9 <= 1 || value < 100) && dmg == ((tmpObj.cheeze ? -10 : 0) - tmpObj.hps)) {
        tmpObj.cheeze = game.tick;
        game.tickBase(() => {
            if (tmpObj.cheeze <= game.tick - 45) tmpObj.cheeze = false;
        }, 46)
    }
    tmpObj.judgeShame();
    //console.log(tmpObj.cheesed, tmpObj.cheeze, tmpObj.cheese)
    if (dmg < 0) {
        if (tmpObj.lastHeal < game.tick) tmpObj.lastHeal = game.tick;
        else {
            tmpObj.macroPoints.qHold += 5;
            tmpObj.hackerPoints.autoheal += 5;
        }
    }
    if (value <= 0) {
        if (tmpObj.alive) tmpObj.reset();
        tmpObj.died = game.tick;
        addMenuChText(null, `${tmpObj.name} [${sid}] has died.`, "red");
        //critical = true;
        //consolelog("crit")
    }
    if (dmg == 3.75 || dmg == ((tmpObj.dot > 0) * 5 + (tmpObj.skinIndex == 7) * 5) - (tmpObj.tailIndex == 13) * 3) {
        if (sid == playerSID) my.reSync = false, bulltickSync = true;
        tmpObj.bullTick = game.tick;
    }
    game.tickBase(() => {
        let attacker = getAttacker(dmg, tmpObj);
        if (attacker) {
            if (attacker[0].weaponVariant == 3 && !(attacker[0].weapon.Pdmg > 20)) tmpObj.dot = 4;
            //if (!(tmpObj.lastAttackers.find2((e) => e[0].sid == attacker[0].sid))) tmpObj.lastAttackers.push([attacker[0], performance.now()]);
        }
    }, 1)
    if (sid == player.sid) {
        if (configs.forceClown || antiPoleAids && ([10, 11, 11.8, 7.5, 8.25, 11.8 * 0.75].includes(dmg) || abs(dmg - 11.8 * 0.75) < 0.01 || abs(dmg - 11.8) < 0.01)) healer();
        else {
            if (qHold && dmg != 5 && dmg > player.shameCount * 3 + 3.5 && player.shameCount < 6) {
                console.log("qhold", qHold)
                console.log(value);
                healer();
                antiInsta = true;
                game.tickBase(() => {
                    antiInsta = false;
                }, 3);
            }
        }
    } else if (value <= 0) {
            tmpObj.alive = false;
            if (turkList.includes(tmpObj.sid) && tmpObj.lastAttackers && tmpObj.lastAttackers.length > 0 && tmpObj.lastAttackers[0][0] === player) {
                setTimeout(() => {
                    packet("6", turkmsg[Math.floor(Math.random() * turkmsg.length)]);
                }, 50);
            }
            game.tickBase(() => {
                addDeadPlayer(tmpObj);
            }, 1);
        }
    if (oldHealth > value) {
        let damage = oldHealth - value;
        let shame = tmpObj.shameCount;
        tmpObj.damaged = oldHealth - value;
    } else if (tmpObj !== player) tmpObj.maxShameCount = mathMax(tmpObj.maxShameCount, tmpObj.shameCount);
    else if (value <= 0) {
        container.style.visibility = "hidden";
        container.style.opacity = "hidden";
    }
}
