globalThis.toR = function(e) {
    var n = ((e * PI) / 180) % (PI2);
    return n > PI ? PI - n : n;
}
globalThis.toD = function(e) {
    var n = ((e / PI) * 360) % 360;
    return n >= 360 ? n - 360 : n;
}
globalThis.findAvailableAnglesR = function(item, thisAng, vel, xd = PI / 60, sid) { // originally 60
    if (!item) return [];
    //   const givenAngle = gAng;
    const interval = xd;
    const potentialAngles = []// {onPlayer:[],norm:[]};
    const x = vel ? player.x3 : player.x2;
    const y = vel ? player.y3 : player.y2;
    const i = items.list[item];
    const tmpS = (35 + i.scale + (i.placeOffset || 0));
    let indx = -1;
    for (let offset = thisAng; offset <= thisAng + PI2; offset += interval) {
        indx++;
        const angle = offset;
        let used = -1;
        const tmpX = x + (tmpS * cos(angle));
        const tmpY = y + (tmpS * sin(angle));
        for (let u = 0; u < usedAngles.length; u++) {
            const usedAngle = usedAngles[u];
            const dx = tmpX - usedAngle.x;
            const dy = tmpY - usedAngle.y;
            if (dx*dx + dy*dy <= 900) {
                used = u;
                break;
            }
        }
        if (used !== -1) continue;
        const obj = { x: tmpX, y: tmpY, id: i.id, re: true, scale: i.scale, indx: indx, angle: angle, offset: tmpS, item: i, collide: [], points: 0, origin: [], name: i.name, overlap: [], preplacer: [], sids: [], intercepts: [], knockback: [] }
        const canPlace = objectManager.checkItemLocation3(tmpX, tmpY, i.scale, 0.6, i.id, false, true, obj, sid);
        if (canPlace) potentialAngles.push(obj);
    }
    //showAngles = potentialAngles;
    return potentialAngles;
}
globalThis.dotAngle = function(x1, y1, x2, y2, x3, y3, max) {
    const ax = x2 - x1;
    const ay = y2 - y1;
    const bx = x3 - x1;
    const by = y3 - y1;
    const dot = ax * bx + ay * by;
    if (dot < 0) return false;
    const magA2 = ax * ax + ay * ay;
    const magB2 = bx * bx + by * by;
    return dot * dot - magA2 * magB2 * max;
}
globalThis.dAngPos = function(a, b, c, max) {
    const x = a.x2 || a.x;
    const y = a.y2 || a.y;
    const ax = (b.x2 || b.x) - x;
    const ay = (b.y2 || b.y) - y;
    const bx = (c.x2 || c.x) - x;
    const by = (c.y2 || c.y) -  y;
    const dot = ax * bx + ay * by;
    if (dot < 0) return false;
    const magA2 = ax * ax + ay * ay;
    const magB2 = bx * bx + by * by;
    return dot * dot - magA2 * magB2 * max;
}
globalThis.dAngFast = function(ax, ay, bx, by, max) {
    const dot = ax * bx + ay * by;
    if (dot < 0) return false;
    const magA2 = ax * ax + ay * ay;
    const magB2 = bx * bx + by * by;
    return dot * dot - magA2 * magB2 * max;
}
