globalThis.bestAim = function(main2, range, objs = nearObjects) {
    const possibleTargets = objs.filter2(obj => obj.active && obj.type === null && obj?.owner?.sid && obj.dist2 <= (range + obj.sczale));
    const startAim = main2;
    let bestAim = startAim; // Default to the current aim
    let concatObj = []
    let maxHitCount = -999;
    let defaultHitCount = 0;
    for (let i = -3; i < 3; i += 1) {
        const aimer = startAim + UWUTILS.toRad(i * 10);
        const hitObjs = [];
        let hitCount = 0;
        for (let j = 0; j < possibleTargets.length; j++) {
            const target = possibleTargets[j];
            if (dAng(caf(player, target), aimer) <= config.gatherAngle) {
                hitObjs.push(target)
                hitCount += ((target?.owner?.sid === player.sid) ? -1 : 0.5);
            }
        }
        if (i == 0) defaultHitCount = hitCount;
        if (hitCount > maxHitCount) {
            maxHitCount = hitCount;
            bestAim = aimer;
            concatObj = hitObjs
        }
    }
    breakObjs.push(concatObj);
    breakObjs = breakObjs.flat();
    return defaultHitCount == maxHitCount ? main2 : bestAim;
}
