globalThis.lowestCollisionDistance = function(plyr, objects, dx, dy) {
    let lowest = Infinity;
    let best = null;
    for (let i = 0;i < objects.length;i++) {
        const obj = objects[i];
        const totalRadius = (40 + obj.escapeScale) ** 2;
        const ox = obj.x - plyr.x2;
        const oy = obj.y - plyr.y2;
        const forwardDist = ox * dx + oy * dy;
        if (forwardDist < 0) continue;
        const closestX = ox - forwardDist * dx;
        const closestY = oy - forwardDist * dy;
        const sideDistSq = closestX * closestX + closestY * closestY;
        if (sideDistSq > totalRadius) continue;
        if (obj.dist2 <= obj.scale + 75) {
            closestCollObj = obj;
            spikeCollDist = 0;
            return;
        }
        const offset = Math.sqrt(totalRadius - sideDistSq);
        const collisionDist = forwardDist - offset;
        if (collisionDist >= lowest) continue;
        lowest = collisionDist;
        best = obj
    }
    closestCollObj = best;
    spikeCollDist = lowest;
}
