function medianOfBuffer(transformValue = null) {
    const predictor = tickPredictor;
    const count = predictor.phaseCount;
    const scratch = predictor.scratch;
    const phases = predictor.phases;

    for (let i = 0; i < count; i++) {
        const value = phases[i];

        scratch[i] = transformValue
            ? transformValue(value)
            : value;
    }

    // Insertion sort is fine for only 32 values and creates no arrays.
    for (let i = 1; i < count; i++) {
        const value = scratch[i];
        let j = i - 1;

        while (j >= 0 && scratch[j] > value) {
            scratch[j + 1] = scratch[j];
            j--;
        }

        scratch[j + 1] = value;
    }

    const middle = count >> 1;

    return count & 1
        ? scratch[middle]
        : (scratch[middle - 1] + scratch[middle]) * 0.5;
}
