    if (!tmpObj || tmpObj.didBotUpdate) return;
    //currPlayers[tmpObj.sid] = tmpObj;
    tmpObj.lastUpdate = Date.now();
    tmpObj.t1 = tmpObj.t2 === undefined ? game.lastTick : tmpObj.t2;
    tmpObj.t2 = game.lastTick;
    tmpObj.oldPos.x2 = tmpObj.x2;
    tmpObj.oldPos.y2 = tmpObj.y2;
    tmpObj.x1 = tmpObj.x;
    tmpObj.y1 = tmpObj.y;
    tmpObj.x2 = data[1];
    tmpObj.y2 = data[2];
    tmpObj.movSpd = cdf(tmpObj.oldPos, tmpObj);
    //tmpObj.guessLocation = `[x: ${100 * tmpObj.x2 / 14400}%, y: ${100 * tmpObj.x2 / 14400}%]`;
    //tmpObj.guessTime = game.tick;
    tmpObj.oldXVel = tmpObj.xVel;
    tmpObj.oldYVel = tmpObj.yVel;
    tmpObj.xVel = tmpObj.x2 - tmpObj.oldPos.x2;
    tmpObj.yVel = tmpObj.y2 - tmpObj.oldPos.y2;
    tmpObj.pmovDir = tmpObj.movDir;
    tmpObj.movDir = (tmpObj.xVel + tmpObj.yVel) <= 7 ? null : UWUTILS.getDirect(tmpObj, tmpObj.oldPos, 2, 2);
    tmpObj.d3 = tmpObj.d2;
    tmpObj.d1 = tmpObj.d2 === undefined ? data[3] : tmpObj.d2;
    tmpObj.d2 = data[3];
    tmpObj.dt = 0;
    tmpObj.oldShameCount = tmpObj.shameCount;
    tmpObj.buildIndex = data[4];
    tmpObj.oldWeaponIndex = tmpObj.weaponIndex;
    tmpObj.weaponIndex = data[5];
    tmpObj.oldLastHealth = tmpObj.lastHealth;
    tmpObj.lastHealth = tmpObj.health;
    if (tmpObj.weaponIndex < 9) tmpObj.weaponReload = tmpObj.primaryReload;
    else tmpObj.weaponReload = tmpObj.secondaryReload;
