globalThis.sortItems = function(plyr, item) {
    const  { itemID, age } = item = items.list[item];
    if (age == 4) plyr.hasBoost = !(plyr.hasTrap = itemID == 15);
    else if (age == 7) plyr.utilityType = item;
    else if (item.dmg) plyr.spikeType = item;
    else if (item.healing) plyr.foodType = item;
    else if (item.pps) plyr.millType = item;
    else if (item.spawnPoint) plyr.hasSpawnPad = true;
    else if (item.wall) plyr.wallType = item;
    return;

}
globalThis.buildLines = function(objects) {
globalThis.lines = [];
for (let i = 0; i < objects.length; i++) {
    for (let j = i + 1; j < objects.length; j++) {
    lines.push({
        from: objects[i],
        to: objects[j]
    });
    }
}
return lines;
}
globalThis.connectionLines = [];
globalThis.connectionKeys = new Set();
globalThis.addConnectionLine = function(a, b) {
    const sidA = a.sid;
    const sidB = b.sid;
    const key = sidA < sidB ? sidA + ":" + sidB : sidB + ":" + sidA;
    if (connectionKeys.has(key)) return;
    connectionKeys.add(key);
    connectionLines.push({
        key,
        a,
        b,
        x1: a.x,
        y1: a.y,
        x2: b.x,
        y2: b.y
    });
}
globalThis.renderConnectionLines = function(xOffset, yOffset) {
    if (!connectionLines.length) return;
    mainContext.strokeStyle = "#3e4047";
    mainContext.lineWidth = 1.5;
    mainContext.save();
    mainContext.beginPath();
    for (let i = 0, len = connectionLines.length; i < len; i++) {
        const line = connectionLines[i];
        mainContext.moveTo(line.x1 - xOffset, line.y1 - yOffset);
        mainContext.lineTo(line.x2 - xOffset, line.y2 - yOffset);
    }
    mainContext.stroke();
    mainContext.restore();
    mainContext.strokeStyle = outlineColor;
    mainContext.lineWidth = 5.5;
}
globalThis.removeLineBySid = function(sid) {
    for (let i = connectionLines.length - 1; i >= 0; i--) {
        const line = connectionLines[i];
        if (line.a.sid === sid || line.b.sid === sid) {
            connectionKeys.delete(line.key);
            connectionLines.splice(i, 1);
        }
    }
}
globalThis.gridStatsCache = [];
globalThis.farthestObj = function(from, group) {
    let best = from;
    let bestD2 = -1;

    const fx = from.x;
    const fy = from.y;

    for (let i = 0; i < group.length; i++) {
        const o = group[i];
        if (!o || !o.active) continue;

        const dx = o.x - fx;
        const dy = o.y - fy;
        const d2 = dx * dx + dy * dy;

        if (d2 > bestD2) {
            bestD2 = d2;
            best = o;
        }
    }
}
globalThis.getGridEnds = function(group) {
    if (!group || group.length === 0) return null;
    let first = null;
    for (let i = 0; i < group.length; i++) {
        const o = group[i];
        if (o && o.active) {
            first = o;
            break;
        }
    }
    if (!first) return null;
    let activeCount = 0;
    for (let i = 0; i < group.length; i++) {
        if (group[i] && group[i].active) activeCount++;
    }
    if (activeCount === 1) {
        return {
            a: first,
            b: first,
            midX: first.x,
            midY: first.y,
            dirX: 1,
            dirY: 0,
            len2: 0,
            len: 0,
            count: 1
        };
    }

    const a = farthestObj(first, group);
    const b = farthestObj(a, group);

    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len2 = dx * dx + dy * dy;
    const len = len2 > 0 ? Math.sqrt(len2) : 0;

    return {
        a,
        b,
        midX: (a.x + b.x) * 0.5,
        midY: (a.y + b.y) * 0.5,
    };
    return best;
}
globalThis.getGridStats = function(grid) {
    const group = connectedObjects[grid];
    if (!group || group.length === 0) return null;
    let cx = 0;
    let cy = 0;
    let count = 0;
    for (let i = 0; i < group.length; i++) {
        const o = group[i];
        if (!o || !o.active) continue;
        cx += o.x;
        cy += o.y;
        count++;
    }
    if (count <= 0) return null;
    const mult = 1 / count;
    cx /= mult;
    cy /= mult;
    let radius2 = 0;
    for (let i = 0; i < group.length; i++) {
        const o = group[i];
        if (!o || !o.active) continue;
        const dx = o.x - cx;
        const dy = o.y - cy;
        const d2 = dx * dx + dy * dy;
        if (d2 > radius2) radius2 = d2;
    }

    const stats = {
        centerX: cx,
        centerY: cy,
        radius: radius2,
        count
    };

    gridStatsCache[grid] = stats;

    return stats;
}
globalThis.intervalStarts = [];
globalThis.intervalEnds = [];

globalThis.addMergedInterval = function(a, b, n) {
    let lo = 0;
    let hi = n;

    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (intervalEnds[mid] < a) lo = mid + 1;
        else hi = mid;
    }

    const i = lo;

    if (i < n && intervalStarts[i] <= b) {
        if (intervalStarts[i] < a) a = intervalStarts[i];
        if (intervalEnds[i] > b) b = intervalEnds[i];

        let j = i + 1;
        while (j < n && intervalStarts[j] <= b) {
            if (intervalEnds[j] > b) b = intervalEnds[j];
            j++;
        }

        intervalStarts[i] = a;
        intervalEnds[i] = b;

        const removed = j - i - 1;
        if (removed > 0) {
            for (let k = i + 1, stop = n - removed; k < stop; k++) {
                intervalStarts[k] = intervalStarts[k + removed];
                intervalEnds[k] = intervalEnds[k + removed];
            }
            n -= removed;
        }
    } else {
        for (let k = n; k > i; k--) {
            intervalStarts[k] = intervalStarts[k - 1];
            intervalEnds[k] = intervalEnds[k - 1];
        }

        intervalStarts[i] = a;
        intervalEnds[i] = b;
        n++;
    }

    return n;
}

globalThis.surroundAngleWidth = function(enemyX, enemyY, spikes) {
    let n = 0;
    const timeStart = performance.now();
    for (let i = 0, len = spikes.length; i < len; i++) {
        const o = spikes[i];
        if (!o || !o.active) continue;
        const dx = o.x - enemyX;
        const dy = o.y - enemyY;
        const d2 = dx * dx + dy * dy;
        if (d2 <= 1) return PI2;
        const r = o.escapeScale;
        if (d2 <= r * r) return PI2;
        const invD = 1 / sqrt(d2);
        let center = fastAtan2(dy, dx);
        if (center < 0) center += PI2;
        const half = asin(r * invD);
        const a = center - half;
        const b = center + half;
        if (a < 0) {
            n = addMergedInterval(a + PI2, PI2, n);
            n = addMergedInterval(0, b, n);
        } else if (b >= PI2) {
            n = addMergedInterval(a, PI2, n);
            n = addMergedInterval(0, b - PI2, n);
        } else {
            n = addMergedInterval(a, b, n);
        }
    }

    let total = 0;
    for (let i = 0; i < n; i++) {
        total += intervalEnds[i] - intervalStarts[i];
    }
    console.log(performance.now() - timeStart, total);
    return total;
}
// LOAD GAME OBJECT:
globalThis.loadGameObject = function(data) {
    //if (!player) return;
    for (let i = 0; i < data.length;) {
        const ownerSid = data[i + 7], objType = data[i + 6], xPos = data[i + 1], yPos = data[i + 2];
        const tmpObj = findPlayerBySID(ownerSid);
        if (tmpObj) {
            const item = objType
            sortItems(tmpObj, item);
            if (objType == 16 && !checkIsTeam(tmpObj.sid) && squareDist(xPos - player.x2, yPos - player.y2) <= 250000) tmpObj.boosted = game.tick;
            // sid, x, y, dir, s, type, data, setSID, owner
        }
        const newSid = data[i];
        for (let z = 0; z < gameObjects.length;z++) {
            const obj = gameObjects[z];
            if (obj.sid != newSid) continue;
            removeLineBySid(newSid, 1);
            gameObjects.splice(z, 1);
        }
        const object = objectManager.add(
            newSid,
            xPos,
            yPos,
            data[i + 3],
            data[i + 4],
            data[i + 5],
            items.list[objType],
            true,
            ownerSid >= 0
                ? {
                    sid: ownerSid,
                }
                : null
        );
        object.inClan = checkIsTeam(object?.owner?.sid);
        const objectConnectScale = object.connectScale;
        if (object.dmg || object.isCactus) {
            const affectedGrids = new Set();
            for (let j = 0;j < gameObjects.length;) {
                const obj = gameObjects[j];
                if ((!obj.isCactus && (!obj.dmg || !obj.inClan)) || obj.sid == newSid) {
                    j++;
                    continue;
                }
                if (!obj.active) {
                    gameObjects.splice(j, 1);
                    continue;
                }
                const dx = obj.x - xPos, dy = obj.y - yPos;
                const range = obj.connectScale + objectConnectScale;
                if (dx > range || dx < -range || dy > range || dy < -range) {
                    j++;
                    continue;
                }
                if (dx * dx + dy * dy > range * range) {
                    j++;
                    continue;
                }
                obj.connections.add(newSid);
                object.connections.add(obj.sid);
                addConnectionLine(obj, object);
                const objGrid = obj.grid;
                const objectGrid = object.grid;
                if (!objGrid) {
                    if (!objectGrid) {
                        const grid = (connectedObjects[gridCount] ||= []);
                        grid.push(object);
                        if (!affectedGrids.has(gridCount)) affectedGrids.add(gridCount);
                        grid.push(object, obj), obj.grid = object.grid = gridCount++;
                    } else {
                        const grid = (connectedObjects[objectGrid] ||= []);
                        grid.push(object);
                        if (!affectedGrids.has(objectGrid)) affectedGrids.add(objectGrid);
                        obj.grid = object.grid, grid.push(obj);
                    }
                } else if (!objectGrid) {
                    object.grid = objGrid;
                    const grid = (connectedObjects[objGrid] ||= []);
                    grid.push(object);
                    if (!affectedGrids.has(objGrid)) affectedGrids.add(objGrid);
                } else if (objGrid != objectGrid) {
                    const grid2 = connectedObjects[objGrid] || [];
                    const newGrid = (connectedObjects[objectGrid] ||= []);
                    for (let k = 0; k < grid2.length; k++) {
                        const gridObject = grid2[k];
                        gridObject.grid = objectGrid;
                        newGrid.push(gridObject);
                    }
                    grid2.length = 0;
                    if (!affectedGrids.has(objectGrid)) affectedGrids.add(objectGrid);
                }
                j++;
            }
            for (let k = 0;k < connectedObjects.length;k++) {
                if (!affectedGrids.has(k)) continue;
                getGridStats(k);
            }
        }
        if (ownerSid === player.sid) {
            if (objType == 15) {
                const trap = findObjectBySid(newSid);
                placedTraps.push(trap);
                let points = 0;
                const bitsData = {
                    bits: 0,
                    blocked: 0
                };
                blockStamp++;
                for (let x = 0; x < liztobj.length; x++) {
                    const obj = liztobj[x];
                    if (!obj.isCactus && (!obj.dmg || !obj.inClan)) continue;
                    let dist = trap.dists.get(obj.sid);
                    if (dist == null) {
                        dist = cdf(trap, obj);
                        trap.dists.set(obj.sid, dist);
                    }
                    if (dist > 350) continue;
                    points += 450 / dist + (dist <= 77 + obj.scale) * ((obj.health > 292.05) ? 3 : 1);
                    if (obj.grid != null) {
                        const grid = connectedObjects[obj.grid];
                        if (grid && grid._blockStamp !== blockStamp) {
                            grid._blockStamp = blockStamp;
                            for (let g = 0; g < grid.length; g++) spikeblock(trap, grid[g], player.scale, bitsData);
                        }
                    } else {
                        spikeblock(trap, obj, player.scale, bitsData, dist);
                    }
                }
                const blockedRatio = bitsData.blocked / BLOCK_BUCKETS;
                points += blockedRatio * 5;
                if (blockedRatio > 0.6) {
                    points += 2;
                    points += (blockedRatio > 0.8) * 3;
                }
                trap.spikePoints = points;
            } else if (objType == spikeType) {
                for (let i = 0; i < placedTraps.length; i++) {
                    const trap = placedTraps[i];
                    let points = trap.health <= 292.05 * -3 ? 1 : 0;
                    const bitsData = {
                        bits: 0,
                        blocked: 0
                    };
                    blockStamp++;
                    for (let x = 0; x < liztobj.length; x++) {
                        const obj = liztobj[x];
                        if (!obj.isCactus && (!obj.dmg || !obj.inClan)) continue;
                        let dist = trap.dists.get(obj.sid);
                        if (dist == null) {
                            dist = cdf(trap, obj);
                            trap.dists.set(obj.sid, dist);
                        }
                        if (dist > 350) continue;
                        points += 450 / dist + (dist <= 77 + obj.scale) * ((obj.health > 292.05) ? 3 : 1);
                        if (obj.grid != null) {
                            const grid = connectedObjects[obj.grid];
                            if (grid && grid._blockStamp !== blockStamp) {
                                grid._blockStamp = blockStamp;
                                for (let g = 0; g < grid.length; g++) spikeblock(trap, grid[g], player.scale, bitsData);
                            }
                        } else {
                            spikeblock(trap, obj, player.scale, bitsData, dist);
                        }
                    }
                    const blockedRatio = bitsData.blocked / BLOCK_BUCKETS;
                    points += blockedRatio * 5;
                    if (blockedRatio > 0.6) {
                        points += 2;
                        points += (blockedRatio > 0.8) * 3;
                    }
                    trap.spikePoints = points;
                }
            }
        }
        i += 8;
    }
}
globalThis.isPointEscapable = function(buildings, target/*, leniance = 80*/) {
    if (buildings.length <= 2) return true; // nothing blocking
    x = target.x2 || target.x;
    y = target.y2 || target.y;
    const isPlayer = target.isPlayer && target.sid === player.sid;
    // compute angle of each building relative to target
    for (let i = 0;i < buildings.length;i++) {
        const b = buildings[i];
        if (b.trap && player.isTeam(b.owner.sid) == isPlayer) continue;
        angles.push({
            building: b,
            angle: isPlayer ? b.aim2 : fastAtan2(b.x - x, b.y - y)
        })
    }
    // sort buildings by angle around the target
    angles.sort((a, b) => a.angle - b.angle);
    // go through each neighboring pair in angular order
    for (let i = angles.length; i > 0;) {
        i--;
        const a = angles[i].building;
        const b = angles[i == 0 ? angles.length - 1 : i - 1].building; // wrap around for circular scan
        // distance between building edges
        const edgeDistance = squareCdf(a, b);
        if (edgeDistance >= 33856) { // 52 + 52 + 80
            // check if any other building blocks the path through this gap
            const midX = (a.x + b.x) * 0.5;
            const midY = (a.y + b.y) * 0.5;
            let blocked = false;
            for (const other of buildings) {
                if (other === a || other === b) continue;
                // distance from other building to line segment (target -> mid gap)
                const t = Math.max(0, Math.min(1, ((other.x - x) * (midX - x) + (other.y - y) * (midY - y)) / ((midX - x)**2 + (midY - y)**2)));
                const closestX = x + t * (midX - x);
                const closestY = y + t * (midY - y);
                const dist = squareDist(other.x - closestX, other.y - closestY);
                if (dist < (other.scale + 40) ** 2) {
                    blocked = true;
                    break;
                }
            }
            if (!blocked) return true; // found a real escapable gap
        }
    }
    return false; // no gaps around the player are escapable
}
