globalThis.getBotSyncAim = function(bot, aimToEnemy) {
    bot.vel = calcAccel(bot, aimToEnemy);
    bot.x3 = bot.vel.x2, bot.y3 = bot.vel.y2;
    const dx = syncTarget.x3 - bot.x3, dy = syncTarget.y3 - bot.y3, vx = syncTarget.x4 - syncTarget.x3, vy = syncTarget.y4 - syncTarget.y3;
    const a = syncTarget.newXVel * syncTarget.newXVel + syncTarget.newYVel * syncTarget.newYVel - 1600;
    const b = 2 * (dx * syncTarget.newXVel + dy * syncTarget.newYVel);
    const c = dx * dx + dy * dy;
    const disc = b * b - 4 * a * c;
    if (disc < 0) return aimToEnemy;
    let t;
    if (abs(a) < 0.0001) return aimToEnemy;
    else {
        const sqrtDisc = sqrt(disc);
        const t1 = (-b - sqrtDisc) / (2 * a);
        const t2 = (-b + sqrtDisc) / (2 * a);
        t = Math.min(t1, t2);
        if (t < 0) t = Math.max(t1, t2);
    }
    if (t < 0) return fastAtan2(syncTarget.y3 - bot.y3, syncTarget.x3 - bot.x3);
    return fastAtan2(syncTarget.y3 + syncTarget.newYVel * t - bot.y3, syncTarget.x3 + syncTarget.newXVel * t - bot.x3);
}
globalThis.shieldBlock = function(attacker, shielder){
    if (shielder.weaponIndex != 11) return false;
    return dAng(caf(shielder, attacker), shielder.d2) <= 1.0471975512
}
