                    bot.syncAim = dist <= bot.syncRange1 ? (Math.random() * 0.06 - 0.03 + bot.aimToSyncEnemy) :
                                dist <= bot.syncRange2 ? (Math.random() * 0.03 - 0.015 + fastAtan2(syncTarget.y4 - bot.y2, syncTarget.x4 - bot.x2)) :
                                dist <= bot.syncRange3 ? (Math.random() * 0.02 - 0.01 + fastAtan2(syncTarget.y5 - bot.y2, syncTarget.x5 - bot.x2)) :
                                (Math.random() * 0.02 - 0.01 + fastAtan2(syncTarget.y6 - bot.y2, syncTarget.x6 - bot.x2));
                    bot.place1 = bot.place2 = bot.place3 = null;
                    if (animalCollision(bot, bot.syncAim, dist)) continue;
