globalThis.translationCache = new Map(
    JSON.parse(localStorage.getItem("translation_cache") || "[]")
);

globalThis.shouldSkipTranslation = function(text) {
    const cleaned = text.trim();
    if (!cleaned) return true;
    if (/^https?:\/\//i.test(cleaned)) return true;
    return false;
}
globalThis.isProbablyEnglish = function(text) {
    const cleaned = text.trim();
    const commonEnglishWords = /\b(niga|nah|e|eh|what|nga|ew|1v1|the|taht|teh|be|and|you|are|is|to|for|of|in|that|this|with|have|not|can|do|dont|will|just|gg|lol|bruh|bro|hello|hi|thanks|please)\b/i;
    if (text == "ty" || commonEnglishWords.test(cleaned)) return true;
    return false;
}
async function translateMessageToEnglish(text) {
    const original = String(text);
    const replaced = original.replaceAll("gonna", "going to").replaceAll("wanna", "want to").replaceAll("imma", "i'm going to").replaceAll("boutta", "about to").replaceAll("tryna", "trying to").replaceAll("til", "until");
    const key = replaced.trim().toLowerCase();
    if (!/[a-z]/g.test(replaced) || shouldSkipTranslation(replaced) || isProbablyEnglish(replaced)) return original;
    const res = await fetch(`https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=en&dt=t&q=${encodeURIComponent(replaced)}`);
    if (!res.ok) {
        console.error(data);
        throw new Error(data.error?.message || "Translation failed");
    }
    const data = await res.json();
    const translation = data[0][0][0];
    const language = data[8][0];
    if (language == "en" || translation.toLowerCase().replace(".", "") == text.toLowerCase()) return original;
    const withLanguage = "en: " + translation.toLowerCase();
    return language + ": " + text + ", " + withLanguage;
}
