// RENDER LEAF:
globalThis.renderLeaf = function(x, y, l, r, ctxt) {
    let endX = x + l * cos(r);
    let endY = y + l * sin(r);
    let width = l * 0.4;
    ctxt.moveTo(x, y);
    ctxt.beginPath();
    ctxt.quadraticCurveTo(
        (x + endX) * 0.5 + width * cos(r + PI * 0.5),
        (y + endY) * 0.5 + width * sin(r + PI * 0.5),
        endX,
        endY
    );
    ctxt.quadraticCurveTo(
        (x + endX) * 0.5 - width * cos(r + PI * 0.5),
        (y + endY) * 0.5 - width * sin(r + PI * 0.5),
        x,
        y
    );
    ctxt.closePath();
    ctxt.fill();
    ctxt.stroke();
}
